func (c *Core) eriOpenImpl(sp *ERIStream, inHigh, inLow, inClose []float64, startIdx, optInTimePeriod int32, outBegIdx, outNBElement *int32, outBullPower, outBearPower []float64, outStride int32) RetCode {
	if len(inHigh) > IndexMax+1 {
		return OutOfRangeEndIndex
	}
	historyLen := int32(len(inHigh))
	endIdx := historyLen - 1
	if len(inLow) != len(inHigh) || len(inClose) != len(inHigh) {
		return BadParam
	}
	if optInTimePeriod == IntegerDefault {
		optInTimePeriod = 13
	} else if optInTimePeriod < 1 || optInTimePeriod > 100000 {
		return BadParam
	}
	if optInTimePeriod == 1 {
		var outIdx int32
		var today int32
		var lookbackTotal int32
		var prevMA float64
		var tempReal float64
		var k float64
		var beta float64
		var tempHT float64
		var tempLT float64
		lookbackTotal = c.eriLookback(optInTimePeriod)
		if startIdx < lookbackTotal {
			startIdx = lookbackTotal
		}
		if startIdx > endIdx {
			*outBegIdx = 0
			*outNBElement = 0
			return InsufficientHistory
		}
		outIdx = 0
		today = startIdx
		for today <= endIdx {
			tempHT = inHigh[today]
			tempLT = inLow[today]
			tempReal = inClose[today]
			outBullPower[outIdx*outStride] = tempHT - tempReal
			outBearPower[outIdx*outStride] = tempLT - tempReal
			outIdx += 1
			today += 1
		}
		*outBegIdx = startIdx
		*outNBElement = outIdx
		sp.optInTimePeriod = optInTimePeriod
		sp.prevMA = prevMA
		sp.k = k
		sp.beta = beta
		sp.cur_outBullPower = outBullPower[(*outNBElement-1)*outStride]
		sp.cur_outBearPower = outBearPower[(*outNBElement-1)*outStride]
		return Success
	} else {
		var outIdx int32
		var today int32
		var lookbackTotal int32
		var i int32
		var prevMA float64
		var tempReal float64
		var k float64
		var beta float64
		var tempHT float64
		var tempLT float64
		lookbackTotal = c.eriLookback(optInTimePeriod)
		if startIdx < lookbackTotal {
			startIdx = lookbackTotal
		}
		if startIdx > endIdx {
			*outBegIdx = 0
			*outNBElement = 0
			return InsufficientHistory
		}
		beta = float64(optInTimePeriod-1) / float64(optInTimePeriod+1)
		k = 1.0 - beta
		if beta < 0.5 {
			beta = 1.0 - k
		}
		today = startIdx - lookbackTotal
		i = optInTimePeriod
		tempReal = 0.0
		for {
			_C0 := i > 0
			i--
			if !_C0 {
				break
			}
			tempReal += inClose[today]
			today++
		}
		prevMA = tempReal / float64(optInTimePeriod)
		for today <= startIdx {
			prevMA = math.FMA(beta, prevMA, float64(k*inClose[today]))
			today++
		}
		tempHT = inHigh[startIdx]
		tempLT = inLow[startIdx]
		outBullPower[0*outStride] = tempHT - prevMA
		outBearPower[0*outStride] = tempLT - prevMA
		outIdx = 1
		for today <= endIdx {
			prevMA = math.FMA(beta, prevMA, float64(k*inClose[today]))
			tempHT = inHigh[today]
			tempLT = inLow[today]
			outBullPower[outIdx*outStride] = tempHT - prevMA
			outBearPower[outIdx*outStride] = tempLT - prevMA
			outIdx += 1
			today += 1
		}
		*outBegIdx = startIdx
		*outNBElement = outIdx
		sp.optInTimePeriod = optInTimePeriod
		sp.prevMA = prevMA
		sp.k = k
		sp.beta = beta
		sp.cur_outBullPower = outBullPower[(*outNBElement-1)*outStride]
		sp.cur_outBearPower = outBearPower[(*outNBElement-1)*outStride]
		return Success
	}
}

